  /*find the repair with provided repair id and staff with provided staff id and
   *if the repair and staff are exist then save a new approval history with provided info
   *and if it is not reject if the process status is 0 and the role is 1, set the process to 1
   *if the process status is 1 and the role is 2 then set tht process to 2
   *if the process status is 2 and the role is 3 then set the process to 3
   *if it is rejected, set the process to 5, finally save the repair instance*/
  approve(
    sid: number,
    rid: number,
    reject: boolean,
    suggestion: string,
  ): ApprovalHistory {
    /*Definition Start*/
    let repair: Repair = l({
      logic: () =>
        getRepository(Repair).find(
          (r: any) =>
            l({
              logic: () => r.Id === rid,
              description: "r.Id=rid",
            }).build().pass,
        ),
      description: "Repair.allInstance()->any(r|r.Id=rid)",
    }).build().pass;
    let staff: Staff = l({
      logic: () =>
        getRepository(Staff).find(
          (s: any) =>
            l({
              logic: () => s.Id === sid,
              description: "s.Id=sid",
            }).build().pass,
        ),
      description: "Staff.allInstance()->any(s|s.Id=sid)",
    }).build().pass;
    let newApprovalHistory: ApprovalHistory;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(repair) === false,
        description: "repair.oclIsUndefined()=false",
      })
        .and({
          logic: () => StandardOPs.oclIsUndefined(staff) === false,
          description: "staff.oclIsUndefined()=false",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newApprovalHistory: ApprovalHistory;
    return l({
      execute: () => (newApprovalHistory = new ApprovalHistory()),
      description: "newApprovalHistory.oclIsNew()",
    })
      .and({
        execute: () => getRepository(ApprovalHistory).push(newApprovalHistory),
        description:
          "ApprovalHistory.allInstance()->includes(newApprovalHistory)",
      })
      .and({
        execute: () => (newApprovalHistory.StaffId = staff.Id),
        description: "newApprovalHistory.StaffId=staff.Id",
      })
      .and({
        execute: () => (newApprovalHistory.Reject = reject),
        description: "newApprovalHistory.Reject=reject",
      })
      .and({
        execute: () => (newApprovalHistory.Suggestion = suggestion),
        description: "newApprovalHistory.Suggestion=suggestion",
      })
      .and({
        execute: () =>
          l().if({
            logic: () =>
              l({
                logic: () => reject === false,
                description: "reject=false",
              })
                .and({
                  logic: () => repair.Process === 0,
                  description: "repair.Process=0",
                })
                .and({
                  logic: () => staff.Role === 1,
                  description: "staff.Role=1",
                }),
            description: "reject=falseandrepair.Process=0andstaff.Role=1",
            then: l({
              execute: () => (repair.Process = 1),
              description: "repair.Process=1",
            }),
            else: l().if({
              logic: () =>
                l({
                  logic: () => repair.Process === 1,
                  description: "repair.Process=1",
                }).and({
                  logic: () => staff.Role === 2,
                  description: "staff.Role=2",
                }),
              description: "repair.Process=1andstaff.Role=2",
              then: l({
                execute: () => (repair.Process = 2),
                description: "repair.Process=2",
              }),
              else: l().if({
                logic: () =>
                  l({
                    logic: () => repair.Process === 2,
                    description: "repair.Process=2",
                  }).and({
                    logic: () => staff.Role === 3,
                    description: "staff.Role=3",
                  }),
                description: "repair.Process=2andstaff.Role=3",
                then: l({
                  execute: () => (repair.Process = 3),
                  description: "repair.Process=3",
                }),
                else: l().if({
                  logic: () =>
                    l({
                      logic: () => reject === true,
                      description: "reject=true",
                    }),
                  description: "reject=true",
                  then: l({
                    execute: () => (repair.Process = 5),
                    description: "repair.Process=5",
                  }),
                  else: l({
                    logic: () => true,
                    description: "true",
                  }),
                }),
              }),
            }),
          }),
        description:
          "(ifreject=falseandrepair.Process=0andstaff.Role=1thenrepair.Process=1elseifrepair.Process=1andstaff.Role=2thenrepair.Process=2elseifrepair.Process=2andstaff.Role=3thenrepair.Process=3elseifreject=truethenrepair.Process=5elsetrueendifendifendifendif)",
      })
      .and({
        execute: () => getRepository(Repair).push(repair),
        description: "Repair.allInstance()->includes(repair)",
      })
      .and({
        execute: () => newApprovalHistory,
        description: "result=newApprovalHistory",
